package com.shoply.infrastructure.security;
import com.auth0.jwt.*; import com.auth0.jwt.algorithms.Algorithm; import com.auth0.jwt.interfaces.DecodedJWT; import com.shoply.application.port.TokenIssuer; import com.shoply.domain.model.User; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtTokenService implements TokenIssuer { private final Algorithm algorithm; private final JWTVerifier verifier; private final long hours; public JwtTokenService(@Value("${shoply.jwt.secret}")String secret,@Value("${shoply.jwt.expiration-hours}")long hours){algorithm=Algorithm.HMAC256(secret);verifier=JWT.require(algorithm).build();this.hours=hours;} public String issue(User u){return JWT.create().withSubject(u.id().toString()).withClaim("email",u.email()).withClaim("role",u.role()).withExpiresAt(Date.from(Instant.now().plus(hours,ChronoUnit.HOURS))).sign(algorithm);} public DecodedJWT verify(String token){return verifier.verify(token);} }
